with flattened_attrs as (select id, currency, tier_prices, element_at(tier_prices, 1) as entry_price, slice(tier_limits, 1, 2) as first_two_limits, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, aggregate(tier_prices, cast(0 as double), (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price from price_tiers) select case when entry_price >= 26 then 'LARGE' else 'SMALL' end as entry_price_tier, round(avg(entry_price), 2) as avg_entry_price, avg(entry_price) filter (where currency = 'USD') as usd_avg_entry_price, sort_array(collect_set(currency)) as currency_list, round(sum(avg_tier_price) / nullif(count(case when currency = 'EUR' then 1 end), 0), 2) as avg_tier_price_per_eur, sum(avg_tier_price) filter (where currency = 'THB') as thb_total_avg_tier_price from flattened_attrs group by case when entry_price >= 26 then 'LARGE' else 'SMALL' end
